agent_detail.agent_sql:
SELECT (COUNT(?c) AS ?n)
WHERE {
  ?c a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> .
}

SELECT (SUM(?claim_amount) AS ?totalExpensePayment) ?company_claim_number
WHERE {
  ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/hasClaimAmount> ?ca .
  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?claim_amount ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim .
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
}
GROUP BY ?company_claim_number

SELECT ?company_claim_number (SUM(?amount) AS ?total)
WHERE {
  {
    ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/hasClaimAmount> ?ca .
    ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amount ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?c .
    ?c a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
  }
  UNION
  {
    ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/hasClaimAmount> ?ca2 .
    ?ca2 a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amount ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?c2 .
    ?c2 a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
  }
}
GROUP BY ?company_claim_number

SELECT ?policy_number ?party_identifier WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?party_identifier ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?p .
  ?p a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
     <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .
}
ORDER BY ?policy_number ?party_identifier

SELECT ?company_claim_number WHERE {
  ?c a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
     <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number ;
     <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_close_date> ?close_date .
  FILTER(STRSTARTS(STR(?close_date), "2019"))
}

SELECT ?lossPaymentAmt ?lossReserveAmt ?expensePaymentAmt ?expenseReserveAmt ?claimNumber ?policyNumber ?policyHolder ?premiumAmt ?agent
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claimNumber .

  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd .

  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policyNumber .

  ?aprH a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "PH" ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?policyHolder .

  ?aprA a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agent .

  OPTIONAL {
    SELECT ?claim (SUM(?lpAmt) AS ?lossPaymentAmt) WHERE {
      ?lca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
           <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
           <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?lpAmt .
      ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/hasClaimAmount> ?lca .
    } GROUP BY ?claim
  }

  OPTIONAL {
    SELECT ?claim (SUM(?lrAmt) AS ?lossReserveAmt) WHERE {
      ?lrca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?lrAmt .
      ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/hasClaimAmount> ?lrca .
    } GROUP BY ?claim
  }

  OPTIONAL {
    SELECT ?claim (SUM(?epAmt) AS ?expensePaymentAmt) WHERE {
      ?epca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?epAmt .
      ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/hasClaimAmount> ?epca .
    } GROUP BY ?claim
  }

  OPTIONAL {
    SELECT ?claim (SUM(?erAmt) AS ?expenseReserveAmt) WHERE {
      ?erca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?erAmt .
      ?er a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve/hasClaimAmount> ?erca .
    } GROUP BY ?claim
  }

  OPTIONAL {
    SELECT ?policy (SUM(?paAmt) AS ?premiumAmt) WHERE {
      ?pa a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/hasPolicy> ?policy ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?paAmt .
      ?prem a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium/hasPolicyAmount> ?pa .
    } GROUP BY ?policy
  }
}

SELECT ?company_claim_number (SUM(?amount) AS ?totalLoss)
WHERE {
  {
    ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caid .
  } UNION {
    ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caid .
  } UNION {
    ?ep a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpensePayment/claimAmountIdentifier> ?caid .
  } UNION {
    ?er a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve> ;
        <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ExpenseReserve/claim_amount_identifier> ?caid .
  }
  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caid ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amount .
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_identifier> ?claimId ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?company_claim_number .
}
GROUP BY ?company_claim_number

SELECT ?policy_number (AVG(?days) AS ?avgDays)
WHERE {
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_open_date> ?open ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/claim_close_date> ?close .

  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd .

  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number .

  BIND((xsd:date(?close) - xsd:date(?open)) AS ?days)
}
GROUP BY ?policy_number

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?n) WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agentId ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policy .
}
GROUP BY ?agentId

SELECT (SUM(?amt) / COUNT(DISTINCT ?pol) AS ?avgPolicySize)
WHERE {
  ?premium a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium> ;
           <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Premium/hasPolicyAmount> ?pa .
  ?pa a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/policy_amount> ?amt ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyAmount/hasPolicy> ?pol .
}

SELECT ?policyNumber ?claimNumber WHERE {
  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd .
  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .
  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policyNumber .
  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claimNumber .
}

SELECT ?agentId ?policyNumber ?claimNumber (SUM(?amount) AS ?lossPaymentAmount)
WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "AG" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?agentId ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/hasPolicy> ?policy .

  ?policy a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policyNumber .

  ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/hasPolicy> ?policy .

  ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasPolicyCoverageDetail> ?pcd ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/hasClaim> ?claim .

  ?claim a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Claim/company_claim_number> ?claimNumber .

  ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/hasClaim> ?claim ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amount .

  ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
      <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/hasClaimAmount> ?ca .
}
GROUP BY ?agentId ?policyNumber ?claimNumber

SELECT ?policy_identifier ?party_identifier WHERE {
  ?apr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole> ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_role_code> "PH" ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/agreement_identifier> ?policy_identifier ;
       <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/AgreementPartyRole/party_identifier> ?party_identifier .
}

SELECT ?policy_number (AVG(?claimLoss) AS ?avgLoss)
WHERE {
  {
    SELECT ?policy_number ?claim_identifier (SUM(?amt) AS ?claimLoss)
    WHERE {
      ?p a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy> ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_number> ?policy_number ;
         <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/Policy/policy_identifier> ?polId .
      ?pcd a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail> ;
           <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/policyIdentifier> ?polId ;
           <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/PolicyCoverageDetail/policyCoverageDetailIdentifier> ?pcdId .
      ?cc a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/policy_coverage_detail_identifier> ?pcdId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimCoverage/claim_identifier> ?claim_identifier .
      ?ca a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount> ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_identifier> ?claim_identifier ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount_identifier> ?caId ;
          <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/ClaimAmount/claim_amount> ?amt .
      {
        ?lp a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossPayment/claim_amount_identifier> ?caId .
      }
      UNION
      {
        ?lr a <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve> ;
            <http://cwd-cwd_acme-ontology-20261002-160605/ontology/vkg-cwd_acme/LossReserve/claim_amount_identifier> ?caId .
      }
      UNION
